function useCountdown(endTimestamp) {
  const [seconds, setSeconds] = useState(endTimestamp ? Math.max(0, Math.ceil((endTimestamp - Date.now()) / 1000)) : null);
  useEffect(() => { if (!endTimestamp) { setSeconds(null); return undefined; } const tick = () => setSeconds(Math.max(0, Math.ceil((endTimestamp - Date.now()) / 1000))); tick(); const id = setInterval(tick, 250); return () => clearInterval(id); }, [endTimestamp]);
  return seconds;
}
function getTournamentVoiceMatch(state, playerId) {
  const matches = Object.values(state?.matches || {});
  const currentPhase = state?.phase;
  const phaseOrder = currentPhase === MODE_PHASES.SEMI_FINALS
    ? ['semi_a', 'semi_b']
    : currentPhase === MODE_PHASES.TRANSITION || currentPhase === MODE_PHASES.PLAYING
      ? ['final', 'consolation', 'semi_a', 'semi_b']
      : ['final', 'consolation', 'semi_a', 'semi_b'];
  return phaseOrder.map((matchId) => matches.find((match) => match.matchId === matchId && match.playerIds?.includes(playerId))).find(Boolean)
    || matches.find((match) => match.playerIds?.includes(playerId) && ['pending', 'playing', 'finished'].includes(match.status))
    || null;
}
function ConnectionStatus({ state }) { const meta = { idle: ['connecting', 'Connecting to the room...', 'sync'], connecting: ['connecting', 'Connecting to realtime play...', 'sync'], connected: ['connected', 'Realtime connected', 'cloud_done'], recovered: ['recovered', 'Connection recovered - room state refreshed', 'refresh'], reconnecting: ['reconnecting', 'Reconnecting - actions paused until the room is current', 'wifi_off'], 'offline-local': ['local', 'Local mode - no Firebase connection', 'cloud_off'], error: ['error', 'Realtime connection needs attention', 'error'] }[state] || ['connecting', 'Checking realtime connection...', 'sync']; const tone = meta[0] === 'connected' || meta[0] === 'recovered' ? 'border-primary-fixed/30 bg-primary-fixed/10 text-primary-fixed' : meta[0] === 'error' ? 'border-error/40 bg-error/10 text-error' : meta[0] === 'reconnecting' ? 'border-warning/40 bg-warning/10 text-warning' : 'border-white/10 bg-white/5 text-on-surface-variant'; return <div className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-xs ${tone}`} role="status" aria-live="polite"><span className="material-symbols-outlined text-[17px]" aria-hidden="true">{meta[2]}</span><span>{meta[1]}</span></div>; }
function PlayerList({ players, canRemove, onRemove, pendingAction }) { return <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">{players.map((player) => <div key={player.id} className="glass-panel-1 rounded-xl p-3 sm:p-4 border border-white/10 shadow-[0_10px_30px_rgba(0,0,0,0.12)]"><div className="flex items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><img src={getPlayerAvatar(player, getRosterAvatarIndex(players, player))} alt={getPlayerAvatarLabel(player, getRosterAvatarIndex(players, player))} className="h-10 w-10 shrink-0 rounded-full border-2 border-primary-fixed/50 object-cover" loading="lazy" /><div className="min-w-0"><div className="font-headline-sm text-white truncate">{player.name}</div><div className="text-xs text-on-surface-variant">{player.isHost ? 'HOST' : 'PLAYER'} - {player.connected === false ? 'OFFLINE' : 'CONNECTED'}</div></div></div>{canRemove && !player.isHost && <button type="button" disabled={Boolean(pendingAction)} onClick={() => onRemove(player.id)} className="touch-feedback min-h-11 min-w-24 text-[10px] font-semibold px-3 py-2 rounded-lg border border-error/40 text-error disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-error">{pendingAction === 'remove' ? 'REMOVING...' : 'REMOVE'}</button>}</div></div>)}</div>; }
const TEAM_LOBBY_SEATS = 3;

function TeamSlotPreview({ players, actions }) {
  const orderedPlayers = [...players].sort((a, b) => (Number(a.joinOrder) || 999) - (Number(b.joinOrder) || 999));
  const teams = [
    { id: 'team_a', label: 'TEAM A', players: orderedPlayers.filter((player) => player.teamId === 'team_a' || (!player.teamId && orderedPlayers.indexOf(player) < 2)).slice(0, TEAM_LOBBY_SEATS), tone: 'border-primary-fixed/40 text-primary-fixed' },
    { id: 'team_b', label: 'TEAM B', players: orderedPlayers.filter((player) => player.teamId === 'team_b' || (!player.teamId && orderedPlayers.indexOf(player) >= 2)).slice(0, TEAM_LOBBY_SEATS), tone: 'border-secondary-fixed/40 text-secondary-fixed' },
  ];
  return <section className="ng-team-preview ng-competitive-surface glass-panel rounded-3xl p-4 sm:p-5 border border-primary-fixed/20 bg-gradient-to-br from-primary-fixed/10 via-white/5 to-transparent shadow-[0_18px_60px_rgba(0,0,0,0.24)] space-y-4" aria-label="2v2 team slots">
    <div className="ng-team-preview-header flex items-center justify-between gap-3">
      <div>
        <div className="font-label-caps text-label-caps text-primary-fixed">TEAM ASSIGNMENT PREVIEW</div>
        <p className="text-xs leading-5 text-on-surface-variant mt-1">Players are grouped by join order when the host starts. Keep both teams balanced.</p>
      </div>
      <span className="material-symbols-outlined text-primary-fixed" aria-hidden="true">groups</span>
    </div>
    <div className="ng-team-preview-rail ng-readiness-rail rounded-2xl border border-white/10 bg-black/15 px-3 py-3" aria-label={`${players.length} of 4 players connected`}>
      <div className="flex items-center justify-between gap-3"><span className="font-label-caps text-label-caps text-on-surface-variant">SQUAD READINESS</span><span className="font-stats-num text-stats-num text-primary-fixed">{players.length}/4</span></div>
      <div className="mt-2 h-2 overflow-hidden rounded-full bg-white/10" aria-hidden="true"><div className="ng-readiness-rail__fill h-full rounded-full bg-gradient-to-r from-primary-fixed to-secondary-fixed" style={{ width: `${Math.min(100, (players.length / 4) * 100)}%` }} /></div>
      <p className="mt-2 text-xs text-on-surface-variant">{players.length >= 4 ? 'Ready to start.' : `${4 - players.length} ${4 - players.length === 1 ? 'seat remains' : 'seats remain'} before launch.`}</p>
    </div>
    <div className="ng-team-preview-grid grid grid-cols-1 sm:grid-cols-2 gap-3">
      {teams.map((team) => <div key={team.id} className={`ng-team-card rounded-2xl border p-4 sm:p-5 bg-black/10 ${team.tone}`}>
        <div className="flex items-center justify-between gap-3"><div className="font-label-caps text-label-caps">{team.label}</div><span className="text-[10px] tracking-[0.16em] text-on-surface-variant">{team.players.length}/{TEAM_LOBBY_SEATS} READY</span></div>
        <div className="mt-2 space-y-2">
          {Array.from({ length: TEAM_LOBBY_SEATS }, (_, slot) => {
            const player = team.players[slot];
            return <div key={`${team.id}-${slot}`} className="ng-team-slot rounded-xl bg-white/5 px-3 py-3 text-sm flex items-center justify-between gap-2 min-h-12">
              {player ? <img src={getPlayerAvatar(player, getRosterAvatarIndex(orderedPlayers, player))} alt={getPlayerAvatarLabel(player, getRosterAvatarIndex(orderedPlayers, player))} className="h-8 w-8 shrink-0 rounded-full border border-white/25 object-cover" loading="lazy" /> : <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-dashed border-white/25 text-on-surface-variant"><span className="material-symbols-outlined text-[16px]" aria-hidden="true">person_add</span></span>}
              <span className={`min-w-0 flex-1 ${player ? 'text-white truncate' : 'text-on-surface-variant'}`}>{player?.name || `Open slot ${slot + 1}`}</span>
              <span className="ng-team-slot-status text-[10px] text-on-surface-variant shrink-0">{player ? (player.connected === false ? 'OFFLINE' : 'READY') : 'OPEN'}</span>{player?.id === actions?.playerId && <div className="ng-team-switchers flex gap-1 ml-2"><button type="button" onClick={() => (actions.onChangeTeam || actions.changeTeam)('team_a')} disabled={player.teamId === 'team_a'} className="touch-feedback min-h-10 min-w-10 px-2 rounded-lg border border-primary-fixed/40 text-[10px] font-semibold text-primary-fixed disabled:opacity-30">A</button><button type="button" onClick={() => (actions.onChangeTeam || actions.changeTeam)('team_b')} disabled={player.teamId === 'team_b'} className="touch-feedback min-h-10 min-w-10 px-2 rounded-lg border border-secondary-fixed/40 text-[10px] font-semibold text-secondary-fixed disabled:opacity-30">B</button></div>}
            </div>;
          })}
        </div>
      </div>)}
    </div>
  </section>;
}

function TargetCard({ target, ready, shared = Boolean(target?.teamId), mode = 'own', opponentTeamLabel = 'OPPONENT TEAM', variant = '' }) { const isOpponent = mode === 'opponent'; const contextLabel = isOpponent ? 'VISIBLE TARGET' : shared ? 'TEAM SHARED' : 'PRIVATE TARGET'; return <section className={`glass-panel rounded-3xl overflow-hidden border border-primary-fixed/35 bg-gradient-to-br from-primary-fixed/15 via-primary-fixed/5 to-transparent shadow-[0_20px_70px_rgba(0,0,0,0.24)] ${variant}`} aria-label={`${opponentTeamLabel} target`}><div className="ng-target-context px-4 py-3 border-b border-white/10 flex items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="material-symbols-outlined text-primary-fixed" aria-hidden="true">{isOpponent ? 'visibility' : shared ? 'groups' : 'lock'}</span><span className="font-label-caps text-label-caps text-primary-fixed">{isOpponent ? `${opponentTeamLabel} TARGET` : shared ? 'TEAM TARGET' : 'YOUR SECRET TARGET'}</span></div><span className="ng-target-context__badge text-[10px] font-semibold tracking-[0.12em] text-on-surface-variant">{contextLabel}</span></div>{target && ready ? <div className="p-4 flex items-center gap-4"><img src={target.image} alt={target.name} className="w-28 h-28 sm:w-32 sm:h-32 shrink-0 rounded-2xl object-cover border-2 border-primary-fixed/50 shadow-[0_8px_24px_rgba(0,0,0,0.28)]" /><div><div className="font-headline-sm text-white">{target.name}</div></div></div> : <div className="p-6 text-center text-on-surface-variant">Synchronizing target...</div>}</section>; }
function JoinDiagnosticCard({ diagnostic, onClear }) { const [copied, setCopied] = useState(false); if (!diagnostic) return null; const report = ['NEON GUESS Join diagnostic', `Stage: ${diagnostic.stage || 'unknown'}`, `Status: ${diagnostic.status || 'failed'}`, `Code: ${diagnostic.code || 'unknown'}`, `Message: ${diagnostic.message || 'Join failed.'}`, `Correlation: ${diagnostic.correlationId || 'unavailable'}`, `Elapsed: ${Number.isFinite(diagnostic.elapsedMs) ? `${diagnostic.elapsedMs}ms` : 'unavailable'}`, `Browser online: ${diagnostic.connection?.browserOnline == null ? 'unknown' : diagnostic.connection.browserOnline}`, `Network: ${diagnostic.connection?.effectiveType || diagnostic.connection?.connectionType || 'unknown'}`, `Time: ${diagnostic.recordedAt || new Date().toISOString()}`].join('\\n'); const copyReport = async () => { try { await navigator.clipboard.writeText(report); setCopied(true); window.setTimeout(() => setCopied(false), 1800); } catch { setCopied(false); } }; return <section className="mt-3 rounded-xl border border-warning/40 bg-warning/10 p-4 text-left text-warning" role="alert" aria-live="assertive" aria-label="Join diagnostic"><div className="flex items-center justify-between gap-3"><strong className="font-label-caps text-label-caps">JOIN DIAGNOSTIC</strong><span className="text-[10px]">SAFE TO SHARE</span></div><div className="mt-3 grid gap-1 text-xs"><div><span className="text-warning/70">Stage:</span> {diagnostic.stage || 'unknown'}</div><div><span className="text-warning/70">Status:</span> {diagnostic.status || 'failed'}</div><div><span className="text-warning/70">Code:</span> <code className="font-mono">{diagnostic.code || 'unknown'}</code></div><p className="mt-1 break-words">{diagnostic.message || 'Join failed.'}</p><div className="mt-2 grid gap-1 text-[10px] text-warning/80"><div>Correlation: <code className="font-mono">{diagnostic.correlationId || 'unavailable'}</code></div><div>Elapsed: {Number.isFinite(diagnostic.elapsedMs) ? `${diagnostic.elapsedMs}ms` : 'unavailable'} · Browser online: {diagnostic.connection?.browserOnline == null ? 'unknown' : String(diagnostic.connection.browserOnline)}</div><div>Network hint: {diagnostic.connection?.effectiveType || diagnostic.connection?.connectionType || 'unknown'}</div></div></div><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={copyReport} className="min-h-10 rounded-lg border border-warning/50 px-3 py-2 text-xs font-semibold">{copied ? 'COPIED' : 'COPY REPORT'}</button><button type="button" onClick={onClear} className="min-h-10 rounded-lg border border-white/20 px-3 py-2 text-xs text-white/80">DISMISS</button></div></section>; }

function RoomCodeCard({ roomId, openSeats }) { const [feedback, setFeedback] = useState(''); const copyRoomCode = async () => { try { if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(roomId); else { const field = document.createElement('textarea'); field.value = roomId; field.setAttribute('readonly', ''); field.style.position = 'fixed'; field.style.opacity = '0'; document.body.appendChild(field); field.select(); document.execCommand('copy'); field.remove(); } setFeedback('COPIED'); window.setTimeout(() => setFeedback(''), 1800); } catch { setFeedback('COPY FAILED'); } }; const shareRoom = async () => { if (navigator.share) { try { await navigator.share({ title: 'NEON GUESS 2v2 Team Battle', text: `Join my NEON GUESS room with code ${roomId}.`, url: window.location.href }); setFeedback('SHARED'); window.setTimeout(() => setFeedback(''), 1800); return; } catch (error) { if (error?.name === 'AbortError') return; } } await copyRoomCode(); }; return <section className="ng-room-invite-card ng-competitive-surface rounded-2xl border border-primary-fixed/40 bg-primary-fixed/10 p-3 sm:p-4 space-y-3 shadow-[0_14px_44px_rgba(0,0,0,0.18)]" aria-label="Room invitation code"><div className="ng-room-invite-header flex flex-wrap items-start justify-between gap-2"><div className="ng-room-invite-copy"><p className="font-label-caps text-label-caps text-primary-fixed">INVITE YOUR SQUAD</p><h3 className="font-headline-sm text-white mt-1">ROOM CODE</h3><p className="text-sm text-on-surface-variant mt-1">Send this code to the other players, then they choose <span className="text-white">Join Room</span> and paste it.</p></div><span className="ng-room-invite-icon material-symbols-outlined text-primary-fixed text-2xl" aria-hidden="true">qr_code_2</span></div><div className="ng-room-invite-code-row flex flex-col sm:flex-row gap-2"><output className="ng-room-invite-code flex-1 min-h-14 rounded-xl bg-black/30 border border-primary-fixed/30 px-3 py-2 font-stats-num text-xl tracking-[0.22em] text-primary-fixed text-center" aria-label={`Room code ${roomId}`}>{roomId}</output><div className="ng-room-invite-actions ng-button-cluster flex gap-2"><button type="button" onClick={copyRoomCode} className="ng-interactive touch-feedback button-click-motion group min-h-12 flex-1 sm:flex-none rounded-xl border border-primary-fixed/50 bg-primary-fixed/5 px-4 py-3 text-primary-fixed font-label-caps text-label-caps shadow-[0_8px_24px_rgba(0,0,0,0.14)] transition-[transform,background-color,border-color,box-shadow] duration-200 hover:-translate-y-0.5 hover:border-primary-fixed/80 hover:bg-primary-fixed/15 hover:shadow-[0_12px_30px_rgba(0,0,0,0.22)] active:translate-y-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-fixed focus-visible:ring-offset-2 focus-visible:ring-offset-surface" aria-label={`Copy room code ${roomId}`}><span className="material-symbols-outlined align-middle text-[18px]">content_copy</span> {feedback === 'COPIED' ? 'COPIED' : 'COPY'}</button><button type="button" onClick={shareRoom} className="ng-interactive touch-feedback button-click-motion min-h-12 flex-1 sm:flex-none rounded-xl bg-primary-fixed px-4 py-3 text-on-primary-fixed font-label-caps text-label-caps focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-fixed" aria-label={`Share room ${roomId}`}><span className="material-symbols-outlined align-middle text-[18px]">share</span> SHARE</button></div></div><div className="ng-room-invite-footer flex items-center justify-between text-xs text-on-surface-variant" role="status" aria-live="polite"><span>{openSeats} {openSeats === 1 ? 'seat remains' : 'seats remain'}.</span>{feedback && <span className={feedback.includes('FAILED') ? 'text-error' : 'text-primary-fixed'}>{feedback}</span>}</div></section>; }
function TeamRevealTargets({ state, result }) { return <section className="glass-panel rounded-xl p-4 sm:p-5 space-y-3 text-left" aria-label="Round target reveal"><div><div className="font-label-caps text-label-caps text-secondary-fixed">TARGET REVEAL</div><p className="text-sm text-on-surface-variant mt-1">These are the targets each team was protecting in round {result?.roundNumber || state.roundNumber}.</p></div><div className="grid sm:grid-cols-2 gap-3">{Object.values(state.teams || {}).map((team) => { const target = result?.targets?.[team.playerIds[0]]; return <div key={team.teamId} className={`rounded-lg border p-3 ${team.teamId === 'team_a' ? 'border-primary-fixed/40 bg-primary-fixed/5' : 'border-secondary-fixed/40 bg-secondary-fixed/5'}`}><div className="font-label-caps text-label-caps text-on-surface-variant">{team.teamId === 'team_a' ? 'TEAM A TARGET' : 'TEAM B TARGET'}</div>{target ? <div className="mt-3 flex items-center gap-3"><img src={target.image} alt={target.name} className="h-16 w-16 rounded-lg object-cover border border-white/20" /><div><div className="font-headline-sm text-white">{target.name}</div><div className="text-xs text-on-surface-variant mt-1">Shared by {team.playerIds.map((id) => state.players[id]?.name || id).join(' + ')} -</div></div></div> : <div className="mt-3 text-sm text-on-surface-variant">Target unavailable.</div>}</div>; })}</div></section>; }

function TeamScoreboard({ state }) { return <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">{Object.values(state.teams || {}).map((team) => <div key={team.teamId} className={`glass-panel rounded-2xl p-4 sm:p-5 border shadow-[0_12px_36px_rgba(0,0,0,0.16)] ${team.teamId === 'team_a' ? 'border-primary-fixed/40 bg-primary-fixed/5' : 'border-secondary-fixed/40 bg-secondary-fixed/5'}`}><div className="flex items-center justify-between"><span className="font-label-caps text-label-caps text-on-surface-variant">{team.teamId === 'team_a' ? 'TEAM A' : 'TEAM B'}</span><span className="font-stats-num text-stats-num text-white">{team.score}</span></div><div className="mt-3 space-y-1">{team.playerIds.map((id) => <div key={id} className="text-sm text-on-surface-variant truncate">{state.players[id]?.name || id} - {state.playerStats?.[id]?.score || 0} pts</div>)}</div></div>)}</div>; }
function PlayerResultRows({ state, guesses, items }) { return <div className="space-y-2 text-left"><div className="font-label-caps text-label-caps text-on-surface-variant">ALL FOUR PLAYER RESULTS</div>{state.playerIds.map((id) => { const guess = guesses?.[id]; const guessedItem = guess ? items.find((item) => item.id === guess.targetId) : null; const stats = state.playerStats?.[id]; return <div key={id} className="glass-panel rounded-lg p-3 flex items-center justify-between gap-3"><div><div className="text-white">{state.players[id]?.name || id} <span className="text-xs text-on-surface-variant">- {stats?.teamId === 'team_a' ? 'TEAM A' : stats?.teamId === 'team_b' ? 'TEAM B' : ''}</span></div><div className="text-xs text-on-surface-variant">{guess ? `Guessed ${guessedItem?.name || guess.targetId}` : 'No guess recorded'} - {stats?.score || 0} total points</div></div><div className="text-right"><span className={`text-xs font-label-caps ${guess?.correct ? 'text-primary-fixed' : 'text-error'}`}>{guess?.correct ? 'CORRECT' : 'MISS'}</span>{stats?.reward && <div className="text-[10px] text-secondary-fixed mt-1">REWARD +{stats.reward.points}</div>}</div></div>; })}</div>; }
function TeamRoundSnapshotReveal({ result }) { const snapshot = result?.revealSnapshot; const target = snapshot?.target; if (!target) return null; const ownerLabel = snapshot.targetOwnerTeamId === 'team_a' ? 'TEAM A' : 'TEAM B'; return <section className="glass-panel rounded-xl p-4 border border-secondary-fixed/40 bg-secondary-fixed/5 text-left" aria-label="Round snapshot reveal"><div className="flex items-center justify-between gap-3"><div><div className="font-label-caps text-label-caps text-secondary-fixed">ROUND SNAPSHOT - {ownerLabel}</div><p className="text-sm text-on-surface-variant mt-1">The protected target is revealed only after the round is complete.</p></div><span className="material-symbols-outlined text-secondary-fixed">visibility</span></div><div className="mt-3 flex items-center gap-3"><img src={target.image} alt={target.name} className="h-16 w-16 rounded-lg object-cover border border-white/20" /><div><div className="font-headline-sm text-white">{target.name}</div><div className="text-xs text-on-surface-variant mt-1">Verified by both players of {ownerLabel}.</div></div></div></section>; }
