function TournamentBoard({ state, actions, category, setCategory, run, navigate, pendingAction }) { const playerMatches = Object.values(state.matches || {}).filter((match) => match.playerIds?.includes(actions.playerId)); const activeMatches = playerMatches.filter((match) => match.status === 'playing'); const revealMatches = playerMatches.filter((match) => match.status === 'round_result'); const activeMatch = activeMatches.length === 1 ? activeMatches[0] : null; const revealMatch = revealMatches.length === 1 ? revealMatches[0] : null; if (state.phase === MODE_PHASES.TRANSITION) return <TournamentTransition state={state} />; if (activeMatches.length > 1 || revealMatches.length > 1) return <section role="alert" className="ng-tournament-phase-card ng-tournament-conflict glass-panel rounded-2xl p-6 text-center"><span className="ng-tournament-waiting__icon material-symbols-outlined" aria-hidden="true">sync_problem</span><h2 className="font-headline-sm text-headline-sm text-error">MATCH STATE CONFLICT</h2><p className="mt-2 text-on-surface-variant">Your player identity is attached to more than one active tournament branch. Waiting for synchronized state instead of showing another match&apos;s target.</p></section>; if (revealMatch) return <TournamentRoundReveal state={state} match={revealMatch} />; if (state.phase === MODE_PHASES.RESULTS && state.status === 'finished') return <TournamentFinal state={state} actions={actions} category={category || state.category} setCategory={setCategory} isHost={state.hostId === actions.playerId} onRetry={(nextCategory) => run(() => actions.resetTournament(nextCategory), 'retry')} onLobby={() => run(actions.leave, 'leave')} onHome={() => run(async () => { await actions.leave(); navigate('/'); }, 'leave')} pendingAction={pendingAction} />; const completedMatch = Object.values(state.matches || {}).find((match) => match.status === 'finished' && match.playerIds.includes(actions.playerId) && match.result); const finishedSemis = [state.matches.semi_a, state.matches.semi_b].every((match) => match.status === 'finished'); return <div className="ng-tournament-board space-y-6"><div className="ng-tournament-bracket ng-tournament-bracket--semifinals grid sm:grid-cols-2 gap-4"><BracketMatch match={state.matches.semi_a} state={state} active={activeMatch?.matchId === 'semi_a'} /><BracketMatch match={state.matches.semi_b} state={state} active={activeMatch?.matchId === 'semi_b'} /></div><div className="ng-tournament-flow-divider flex justify-center text-secondary-fixed font-label-caps" role="note">WINNERS ADVANCE · LOSERS PLAY FOR 3RD</div><div className="ng-tournament-bracket ng-tournament-bracket--next ng-tournament-bracket--progression grid sm:grid-cols-2 gap-4"><BracketMatch match={state.matches.final} state={state} active={activeMatch?.matchId === 'final'} /><BracketMatch match={state.matches.consolation} state={state} active={activeMatch?.matchId === 'consolation'} /></div>{activeMatch ? <TournamentGameplay state={state} actions={actions} match={activeMatch} /> : completedMatch ? <TournamentMatchResult state={state} match={completedMatch} /> : finishedSemis ? <TournamentTransition state={state} actions={actions} /> : <div className="ng-tournament-phase-card ng-tournament-waiting glass-panel rounded-xl p-5 text-center text-on-surface-variant"><span className="ng-tournament-waiting__icon material-symbols-outlined" aria-hidden="true">hourglass_top</span><div className="ng-tournament-phase-eyebrow font-label-caps text-label-caps text-primary-fixed">MATCH HANDOFF</div><p className="ng-tournament-waiting__copy mt-2">You are waiting for your assigned match to begin. The bracket is synchronized by Firebase.</p></div>}</div>; }
function Lobby({ mode, state, actions, roomId, playerName, setPlayerName, category, setCategory, joinId, setJoinId, players, run, removePlayer, pendingAction }) { const title = mode === COMPETITIVE_MODES.TOURNAMENT ? '4-PLAYER TOURNAMENT' : '2v2 TEAM BATTLE'; if (!state) return <section className={`ng-room-command-deck glass-panel-heavy rounded-xl p-5 sm:p-8 space-y-5 overflow-hidden ${mode === COMPETITIVE_MODES.TOURNAMENT ? 'ng-tournament-lobby' : ''}`}><div className="ng-room-command-deck__header min-w-0"><div className="mb-2 inline-flex items-center gap-2 rounded-full border border-primary-fixed/25 bg-primary-fixed/10 px-3 py-1.5"><span className="material-symbols-outlined text-[16px] text-primary-fixed" aria-hidden="true">diversity_3</span><span className="font-label-caps text-[10px] tracking-[0.16em] text-primary-fixed">ROOM MODE</span></div><p className="font-label-caps text-label-caps text-primary-fixed">PLAY WITH FRIENDS</p><h2 className="font-display-lg text-display-lg text-white break-words">{title}</h2><p className="text-on-surface-variant mt-2 break-words">Create or join a room.</p></div><div className="ng-player-setup-strip grid md:grid-cols-3 gap-3"><input value={playerName} onChange={(e) => setPlayerName(e.target.value)} className="touch-feedback min-h-11 bg-white/5 rounded px-3 py-3 text-white border border-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-fixed" placeholder="Your name" aria-label="Your player name" /><select value={category} onChange={(e) => setCategory(e.target.value)} className="touch-feedback min-h-11 bg-white/5 rounded px-3 py-3 text-white border border-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-fixed" aria-label="Game category">{Object.entries(actions.CATEGORY_META).map(([id, cat]) => <option key={id} value={id}>{cat.label}</option>)}</select><label className="ng-room-join-field rounded-xl border border-primary-fixed/20 bg-primary-fixed/[0.035] px-3 py-2 focus-within:border-primary-fixed/60 focus-within:bg-primary-fixed/[0.07] focus-within:ring-2 focus-within:ring-primary-fixed/25"><span className="ng-room-join-field__signal"><span className="ng-room-join-field__label font-label-caps text-[10px] tracking-[0.14em] text-primary-fixed/80">ROOM JOIN ID</span><span className="ng-room-join-field__hint text-[10px] tracking-[0.1em] text-on-surface-variant">PASTE TO ENTER</span></span><span className="ng-room-join-field__control mt-1 flex items-center gap-2"><span className="material-symbols-outlined text-[18px] text-primary-fixed/80" aria-hidden="true">key</span><input value={joinId} onChange={(e) => setJoinId(e.target.value.toUpperCase())} className="ng-room-join-input touch-feedback min-h-8 min-w-0 flex-1 bg-transparent p-0 text-white placeholder:text-on-surface-variant/70 focus-visible:outline-none" placeholder="Paste room code" aria-label="Room ID to join" aria-describedby="room-join-id-hint" autoCapitalize="characters" inputMode="text" /></span><span id="room-join-id-hint" className="sr-only">Enter the room code shared by the host.</span></label></div><div className={`ng-room-entry-actions ng-room-entry-actions--balanced flex flex-col sm:flex-row gap-3 ${mode === COMPETITIVE_MODES.TOURNAMENT ? 'ng-room-entry-actions--tournament' : ''}`} role="group" aria-labelledby="room-actions-caption"><span id="room-actions-caption" className="ng-room-entry-actions__caption" aria-hidden="true">SELECT AN ENTRY ROUTE</span><button type="button" disabled={Boolean(pendingAction)} aria-busy={pendingAction === 'create'} onClick={() => run(() => actions.createRoom(category), 'create')} className="ng-create-room-action touch-feedback min-h-11 flex-1 bg-primary-fixed text-on-primary-fixed rounded-lg px-4 py-3 font-headline-sm disabled:opacity-40 active:scale-95"><span className="ng-room-entry-action__index" aria-hidden="true">01</span><span className="ng-room-entry-action__meta" aria-hidden="true">NEW ROOM</span><span className="material-symbols-outlined align-middle text-[18px]" aria-hidden="true">add_box</span><span className="ng-room-entry-action__text">{pendingAction === 'create' ? 'Creating...' : 'Create Room'}</span></button><button type="button" disabled={!joinId || Boolean(pendingAction)} aria-busy={pendingAction === 'join'} onClick={() => run(() => actions.joinRoom(joinId), 'join')} className="ng-join-room-action ng-join-room-action--primary touch-feedback min-h-11 flex-1 border border-primary-fixed/50 text-primary-fixed rounded-lg px-4 py-3 font-headline-sm disabled:opacity-40 active:scale-95"><span className="ng-room-entry-action__index" aria-hidden="true">02</span><span className="ng-room-entry-action__meta" aria-hidden="true">PASTE CODE</span><span className="material-symbols-outlined align-middle text-[18px]" aria-hidden="true">login</span><span className="ng-room-entry-action__text">{pendingAction === 'join' ? 'Joining...' : 'Join Room'}</span></button></div></section>; return <section className="glass-panel-heavy rounded-xl p-5 sm:p-8 space-y-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="font-label-caps text-label-caps text-primary-fixed">ROOM {roomId}</p><h2 className="font-display-lg text-display-lg text-white">WAITING ROOM</h2><p className="text-on-surface-variant mt-2">{players.length}/4 · {state.category}</p><div className="mt-3 inline-flex max-w-full items-center gap-2 rounded-full border border-primary-fixed/20 bg-primary-fixed/5 px-3 py-1.5" role="status" aria-live="polite"><span className="material-symbols-outlined text-[16px] text-primary-fixed" aria-hidden="true">groups</span><span className="truncate font-label-caps text-[10px] tracking-[0.12em] text-primary-fixed">ROOM � {players.length}/4 CONNECTED</span></div></div>{state.hostId === actions.playerId && <button type="button" disabled={players.length !== 4 || Boolean(pendingAction)} aria-busy={pendingAction === 'start'} onClick={() => run(() => actions.startMode(state.category), 'start')} className="touch-feedback min-h-11 bg-primary-fixed text-on-primary-fixed rounded-lg px-4 py-3 font-headline-sm disabled:opacity-40">{pendingAction === 'start' ? 'STARTING...' : 'START MATCH'}</button>}</div><RoomCodeCard roomId={roomId} openSeats={Math.max(0, 4 - players.length)} />{mode === COMPETITIVE_MODES.TEAM_BATTLE && <div className="rounded-lg border border-primary-fixed/20 bg-primary-fixed/5 p-3 text-sm" role="status" aria-live="polite" aria-atomic="true"><div className="flex items-center justify-between gap-3"><span className="font-label-caps text-label-caps text-primary-fixed">MATCH READINESS</span><span className="text-white font-semibold">{players.length}/4 SEATS</span></div><p className="mt-1 text-on-surface-variant">{players.length === 4 ? 'Ready to start.' : `${4 - players.length} more ${4 - players.length === 1 ? 'player is' : 'players are'} needed before launch.`}</p></div>}{mode === COMPETITIVE_MODES.TEAM_BATTLE && <TeamSlotPreview players={players} actions={{ ...actions, onChangeTeam: (teamId) => run(() => actions.changeTeam(teamId), 'team') }} />}<PlayerList players={players} canRemove={state.hostId === actions.playerId && state.phase === 'lobby'} onRemove={removePlayer} pendingAction={pendingAction} />{players.length < 4 && <div className="text-center text-sm text-on-surface-variant">Share room <span className="text-primary-fixed">{roomId}</span> with {4 - players.length} more players.</div>}</section>; }
export default function CompetitiveModePage({ mode }) { const navigate = useNavigate(); const actions = useCompetitiveMode(); const { state, roomId, playerName, setPlayerName, status, error, recovery, connectionState, chatMessages, sendChatMessage } = actions; const [category, setCategory] = useState('sports'); const [joinId, setJoinId] = useState(''); const [localError, setLocalError] = useState(''); const [pendingAction, setPendingAction] = useState(''); const players = useMemo(() => Object.values(state?.players || {}), [state]); useEffect(() => { if (state?.phase === MODE_PHASES.RESULTS && state?.category) setCategory(state.category); }, [state?.phase, state?.category]); const run = async (fn, actionKey = 'action') => { if (pendingAction) return; setLocalError(''); setPendingAction(actionKey); try { await fn(); } catch (e) { setLocalError(e.message || 'Action failed.'); } finally { setPendingAction(''); } }; const removePlayer = (id) => run(() => actions.removePlayer(id), 'remove'); const activeVoiceMatch = mode === COMPETITIVE_MODES.TOURNAMENT ? getTournamentVoiceMatch(state, actions.playerId) : state?.match ? { matchId: state.match.matchId || 'team-battle', playerIds: state.playerIds || players.map((player) => player.id) } : null; const voiceRoomId = roomId; const voiceEligibleParticipantIds = activeVoiceMatch?.playerIds || players.map((player) => player.id); return <><main className={`ng-page-shell flex-1 w-full max-w-6xl mx-auto px-container-margin pt-24 pb-32 md:pt-32 relative z-10 flex flex-col gap-stack-lg ${mode === COMPETITIVE_MODES.TOURNAMENT ? 'ng-tournament-shell' : ''}`}><div className={`ng-tournament-command-rail flex items-center justify-between gap-4 ${mode === COMPETITIVE_MODES.TOURNAMENT ? 'ng-tournament-command-rail--four' : ''}`}><div><div className="text-primary-fixed font-label-caps">{mode === COMPETITIVE_MODES.TOURNAMENT ? '4-PLAYER TOURNAMENT' : '2v2 TEAM BATTLE'} · {status}</div><h1 className="font-display-lg text-display-lg text-white">{mode === COMPETITIVE_MODES.TOURNAMENT ? '4-PLAYER TOURNAMENT' : '2v2 TEAM BATTLE'}</h1></div>{roomId && <button type="button" disabled={pendingAction === 'leave'} aria-busy={pendingAction === 'leave'} onClick={() => run(actions.leave, 'leave')} className="ng-tournament-leave touch-feedback min-h-11 px-4 py-2 rounded border border-error/40 text-error disabled:opacity-40">{pendingAction === 'leave' ? 'Leaving...' : 'Leave'}</button>}</div>{roomId && <div className="ng-tournament-session-signals"><ConnectionStatus state={connectionState} /> {state && roomId && voiceRoomId && activeVoiceMatch && <VoiceRoomPanel roomType={mode === COMPETITIVE_MODES.TOURNAMENT ? 'tournament' : 'team-battle'} roomId={voiceRoomId} scopeId={activeVoiceMatch?.matchId || 'team'} playerId={actions.playerId} displayName={playerName} eligibleParticipantIds={voiceEligibleParticipantIds} label={mode === COMPETITIVE_MODES.TOURNAMENT ? 'MATCH VOICE' : 'TEAM VOICE'} compact />}</div>}{roomId && <CompetitiveChatPanel messages={chatMessages} playerId={actions.playerId} onSend={sendChatMessage} disabled={!actions.canMutateCompetitive} />}{recovery?.status === 'pending' && recovery.roomId && <div role="dialog" aria-live="polite" aria-label="Saved room recovery" className="border border-primary/30 text-white rounded-xl p-4 flex flex-wrap items-center justify-between gap-3"><span>Rejoin saved room <strong>{recovery.roomId}</strong>?</span><span className="flex gap-2"><button type="button" onClick={() => run(actions.retrySessionRecovery, 'rejoin')} disabled={Boolean(pendingAction)} className="touch-feedback min-h-10 px-4 rounded-lg bg-primary-fixed text-on-primary font-semibold">Yes</button><button type="button" onClick={actions.clearSessionRecovery} disabled={Boolean(pendingAction)} className="touch-feedback min-h-10 px-4 rounded-lg border border-white/20 text-white/80">No</button></span></div>}{recovery?.status === 'restoring' && <div role="status" aria-live="polite" className="border border-primary/30 text-primary-fixed rounded-lg p-3">Restoring room <strong>{recovery.roomId}</strong>...</div>}{recovery?.status === 'retryable-error' && <div role="alert" aria-live="assertive" className="border border-warning/40 text-warning rounded-lg p-3 flex flex-wrap items-center justify-between gap-3"><span>{recovery.message}</span><span className="flex gap-2"><button type="button" onClick={() => run(actions.retrySessionRecovery, 'rejoin')} disabled={Boolean(pendingAction)} className="touch-feedback min-h-10 px-3 rounded border border-warning/50">Retry</button><button type="button" onClick={actions.clearSessionRecovery} className="touch-feedback min-h-10 px-3 rounded border border-white/20 text-white/70">Forget room</button></span></div>}{recovery?.status === 'identity-error' && <div role="alert" aria-live="assertive" className="border border-error/40 text-error rounded-lg p-3">{recovery.message} <button type="button" onClick={actions.clearSessionRecovery} className="ml-2 underline">Forget saved room</button></div>}{recovery?.status === 'terminal' && <div role="alert" aria-live="assertive" className="border border-error/40 text-error rounded-lg p-3 flex flex-wrap items-center justify-between gap-3"><span>Saved room <strong>{recovery.roomId}</strong> is no longer available. You can create or join another room.</span><button type="button" onClick={actions.clearSessionRecovery} className="touch-feedback min-h-10 px-3 rounded border border-white/20 text-white/80">Clear saved room</button></div>}<JoinDiagnosticCard diagnostic={actions.joinDiagnostic} onClear={actions.clearJoinDiagnostic} />{(error || localError) && <div role="alert" aria-live="polite" className="border border-error/40 text-error rounded-lg p-3 flex flex-wrap items-center justify-between gap-3"><span>{error || localError}</span>{!roomId && actions.retryAuth && <button type="button" onClick={() => run(actions.retryAuth, 'auth-retry')} disabled={Boolean(pendingAction)} className="touch-feedback min-h-10 px-3 rounded border border-error/50 text-error disabled:opacity-40">Retry connection</button>}</div>}{status === 'closed' && !state && <div role="alert" aria-live="assertive" className="border border-warning/40 text-warning rounded-lg p-4">This Team Battle room has ended or was closed. Create a new room or join another room to continue.</div>}{!state || state.phase === MODE_PHASES.LOBBY ? <Lobby mode={mode} state={state} actions={actions} roomId={roomId} playerName={playerName} setPlayerName={setPlayerName} category={category} setCategory={setCategory} joinId={joinId} setJoinId={setJoinId} players={players} run={run} removePlayer={removePlayer} pendingAction={pendingAction} /> : mode === COMPETITIVE_MODES.TOURNAMENT ? <TournamentBoard state={state} actions={actions} category={category} setCategory={setCategory} run={run} navigate={navigate} pendingAction={pendingAction} /> : (state.status === 'round_result' || state.status === 'finished') ? (
      <TeamResult state={state} actions={actions} onDashboard={() => navigate('/')} />
    ) : (
      <TeamBattleGameplay state={state} actions={actions} />
    )}</main></>; }



